CREATE TABLE public.pyqs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, class_id uuid NOT NULL REFERENCES public.classes(id), subject_id uuid NOT NULL REFERENCES public.subjects(id), year integer NOT NULL CHECK(year BETWEEN 1900 AND 2100), file_path text NOT NULL UNIQUE, uploaded_by uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.pyqs TO authenticated;
GRANT ALL ON public.pyqs TO service_role;
ALTER TABLE public.pyqs ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_upload_pyq(_class uuid,_subject uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'super_admin') OR (public.has_role(auth.uid(),'teacher') AND EXISTS(SELECT 1 FROM public.teacher_assignments a JOIN public.sections s ON s.id=a.section_id JOIN public.teachers t ON t.id=a.teacher_id WHERE t.profile_id=auth.uid() AND t.active AND s.class_id=_class AND a.subject_id=_subject)) $$;
CREATE POLICY pyqs_read ON public.pyqs FOR SELECT TO authenticated USING(public.can_upload_pyq(class_id,subject_id) OR (public.has_role(auth.uid(),'student') AND EXISTS(SELECT 1 FROM public.students p JOIN public.sections s ON s.id=p.section_id WHERE p.profile_id=auth.uid() AND p.active AND s.class_id=pyqs.class_id)));
CREATE POLICY pyqs_insert ON public.pyqs FOR INSERT TO authenticated WITH CHECK(uploaded_by=auth.uid() AND public.can_upload_pyq(class_id,subject_id) AND file_path LIKE auth.uid()::text||'/%' AND EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='school-pyqs' AND o.name=file_path AND o.owner_id=auth.uid()::text));
CREATE POLICY pyqs_delete ON public.pyqs FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'super_admin') OR (uploaded_by=auth.uid() AND public.can_upload_pyq(class_id,subject_id)));
CREATE POLICY pyq_files_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='school-pyqs' AND (public.has_role(auth.uid(),'super_admin') OR public.has_role(auth.uid(),'teacher')) AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name))='pdf');
CREATE POLICY pyq_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='school-pyqs' AND (public.has_role(auth.uid(),'super_admin') OR (owner_id=auth.uid()::text AND public.has_role(auth.uid(),'teacher')) OR EXISTS(SELECT 1 FROM public.pyqs p WHERE p.file_path=name)));
CREATE POLICY pyq_files_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='school-pyqs' AND (public.has_role(auth.uid(),'super_admin') OR (owner_id=auth.uid()::text AND public.has_role(auth.uid(),'teacher'))));